+import React, { useEffect, useState } from "react";
+import { Room } from "matrix-js-sdk/src/models/room";
+import { RoomMember } from "matrix-js-sdk/src/models/room-member";
+import { logger } from "matrix-js-sdk/src/logger";
+import { MatrixClientPeg } from "../../MatrixClientPeg";
+import { getPrimaryPermalinkEntity, parsePermalink } from "../utils/permalinks/Permalinks";
+import dis from "../dispatcher/dispatcher";
+import { Action } from "../dispatcher/actions";
+import RoomAvatar from "../components/views/avatars/RoomAvatar";
+import MemberAvatar from "../components/views/avatars/MemberAvatar";
+import { ButtonEvent } from "../components/views/elements/AccessibleButton";
+import { PillType } from "../components/views/elements/Pill";
+
+interface UsePermalinkArgs {
+    room?: Room;
+    type?: PillType;
+    url?: string;
+}
+
+interface HookResult {
+    avatar: React.ReactElement | null;
+    text: string | null;
+    onClick: ((e: ButtonEvent) => void) | null;
+    resourceId: string | null;
+    type: PillType | "space" | null;
+}
+
+export function usePermalink(args: UsePermalinkArgs): HookResult {
+    const { room, type, url } = args;
+    const [resourceId, setResourceId] = useState<string | null>(null);
+    const [member, setMember] = useState<RoomMember | null>(null);
+    const [resolvedRoom, setResolvedRoom] = useState<Room | null>(null);
+    const [profileLoaded, setProfileLoaded] = useState(false);
+
+    useEffect(() => {
+        let localResourceId: string;
+        let prefix: string;
+
+        if (url) {
+            if (room) {
+                const parts = parsePermalink(url);
+                localResourceId = parts.primaryEntityId;
+                prefix = parts.sigil;
+            } else {
+                localResourceId = getPrimaryPermalinkEntity(url);
+                prefix = localResourceId ? localResourceId[0] : undefined;
+            }
+        }
+
+        const resolvedType =
+            type ||
+            {
+                "@": PillType.UserMention,
+                "#": PillType.RoomMention,
+                "!": PillType.RoomMention,
+            }[prefix];
+
+        let localMember: RoomMember;
+        let localRoom: Room;
+
+        switch (resolvedType) {
+            case PillType.AtRoomMention:
+                localRoom = room;
+                break;
+            case PillType.UserMention:
+                const localMemberInRoom = room?.getMember(localResourceId);
+                localMember = localMemberInRoom;
+                if (!localMemberInRoom) {
+                    localMember = new RoomMember(null, localResourceId);
+                    MatrixClientPeg.get()
+                        .getProfileInfo(localResourceId)
+                        .then((resp) => {
+                            localMember.name = resp.displayname;
+                            localMember.rawDisplayName = resp.displayname;
+                            setMember(localMember);
+                            setProfileLoaded(true);
+                        })
+                        .catch((err) => {
+                            logger.error("Could not retrieve profile data for " + localResourceId + ":", err);
+                        });
+                }
+                break;
+            case PillType.RoomMention:
+                const client = MatrixClientPeg.get();
+                localRoom =
+                    localResourceId && localResourceId[0] === "#"
+                        ? client.getRooms().find((r) => r.getCanonicalAlias() === localResourceId || r.getAltAliases().includes(localResourceId))
+                        : client.getRoom(localResourceId);
+                break;
+        }
+
+        setResourceId(localResourceId);
+        setResolvedRoom(localRoom);
+        if (localMember) {
+            setMember(localMember);
+        }
+    }, [url, type, room]);
+
+    let resolvedType: PillType | "space" | null = null;
+    let text: string | null = null;
+    let avatar: React.ReactElement | null = null;
+    let onClick: ((e: ButtonEvent) => void) | null = null;
+
+    if (resourceId) {
+        const client = MatrixClientPeg.get();
+        if (type === PillType.AtRoomMention) {
+            resolvedType = PillType.AtRoomMention;
+            text = "@room";
+            if (room) {
+                avatar = <RoomAvatar room={room} width={16} height={16} aria-hidden="true" />;
+            }
+        } else if (type === PillType.UserMention) {
+            resolvedType = PillType.UserMention;
+            if (member) {
+                const displayName = member.rawDisplayName || member.name || resourceId;
+                text = displayName;
+                avatar = <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />;
+                onClick = (e: ButtonEvent) => {
+                    e.preventDefault();
+                    dis.dispatch({
+                        action: Action.ViewUser,
+                        member: member,
+                    });
+                };
+            } else {
+                text = resourceId;
+            }
+        } else if (type === PillType.RoomMention) {
+            if (resolvedRoom) {
+                resolvedType = resolvedRoom.isSpaceRoom() ? "space" : PillType.RoomMention;
+                text = resolvedRoom.name || resourceId;
+                avatar = <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" />;
+            } else {
+                resolvedType = PillType.RoomMention;
+                text = resourceId;
+            }
+        }
+    }
+
+    return {
+        avatar: avatar,
+        text: text,
+        onClick: onClick,
+        resourceId: resourceId,
+        type: resolvedType,
+    };
+}
